import { mkdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { ingestFeedbackDirectory } from './user-feedback-ingestion.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const defaultOutputDirectory = resolve(repositoryRoot, 'docs/user-testing/evidence/generated');

const postTestLabels = {
  mostConfusing: 'Most confusing part',
  couldNotFind: 'Expected feature not found',
  unclearTerminology: 'Unclear terminology',
  mostIntuitive: 'Most intuitive part',
  oneChange: 'Suggested change',
  comfortableRepeatingTasks: 'Comfortable repeating tasks',
};

function markdownText(value) {
  return String(value).replaceAll('\r\n', '\n').replaceAll('\n', '<br>');
}

function markdownList(values, emptyMessage) {
  if (values.length === 0) return `- ${emptyMessage}`;
  return values.map((value) => `- ${markdownText(value)}`).join('\n');
}

function traceabilityValue(value) {
  return value ? `\`${value}\`` : 'Not recorded';
}

function findingsFor(response) {
  return response.tasks.flatMap((task) =>
    task.findings.map((finding) => ({
      ...finding,
      taskId: task.taskId,
    })),
  );
}

function severityRows(findings) {
  return ['S1', 'S2', 'S3', 'S4']
    .map((severity) => `| ${severity} | ${findings.filter((finding) => finding.severity === severity).length} |`)
    .join('\n');
}

function completionStatus(response) {
  const total = response.tasks.length;
  const count = (outcome) => response.tasks.filter((task) => task.outcome === outcome).length;

  return [
    `- Success: ${count('success')} of ${total}`,
    `- Partial: ${count('partial')} of ${total}`,
    `- Failure: ${count('failure')} of ${total}`,
  ].join('\n');
}

function participantComments(response) {
  const entries = Object.entries(response.postTestResponses);
  if (entries.length === 0) return '- No participant comments recorded.';

  return entries
    .map(([key, value]) => {
      const label = postTestLabels[key] ?? key;
      const content = typeof value === 'boolean' ? (value ? 'Yes' : 'No') : markdownText(value);
      return `- **${label}:** ${content}`;
    })
    .join('\n');
}

export function renderUserTestingEvidence(response) {
  const findings = findingsFor(response);
  const observations = response.tasks.flatMap((task) =>
    task.observations.map((observation) => `${task.taskId}: ${observation}`),
  );
  const problems = findings.map(
    (finding) =>
      `${finding.findingId} (${finding.taskId}, ${finding.severity}): ${finding.summary} ` +
      `Decision: ${finding.decision}.`,
  );

  return `# User Testing Evidence

## Workflow Tested

- **Participant ID:** ${response.participantId}
- **Role:** ${response.role}
- **Session date:** ${response.sessionDate}
- **Workflow:** ${markdownText(response.workflowTested)}

## Tasks Attempted

| Task | Outcome |
| --- | --- |
${response.tasks.map((task) => `| ${task.taskId} | ${task.outcome} |`).join('\n')}

## Completion Status

${completionStatus(response)}

## Observations

${markdownList(observations, 'No observations recorded.')}

## Participant Comments

${participantComments(response)}

## Positive Findings

${markdownList(response.positiveFindings, 'No positive findings recorded.')}

## Usability Problems

${markdownList(problems, 'No usability problems recorded.')}

## Severity Classification

| Severity | Findings |
| --- | ---: |
${severityRows(findings)}

## Suggested Improvements

${markdownList(response.suggestedImprovements, 'No suggested improvements recorded.')}

## Traceability

- **Related Gitea issue:** ${traceabilityValue(response.traceability.relatedGiteaIssue)}
- **Implementation commit:** ${traceabilityValue(response.traceability.implementationCommit)}
- **Retest evidence:** ${traceabilityValue(response.traceability.retestEvidence)}
`;
}

function outputFilename(response) {
  return `${response.sessionDate}-${response.participantId}-${response.role}.md`;
}

export async function generateUserTestingEvidence(inputDirectory, outputDirectory = defaultOutputDirectory) {
  const responses = await ingestFeedbackDirectory(inputDirectory);
  const filenames = new Set();

  for (const response of responses) {
    const filename = outputFilename(response);
