  const outputPaths = await Promise.all(
    responses.map(async (response) => {
      const outputPath = resolve(outputDirectory, outputFilename(response));
      await writeFile(outputPath, renderUserTestingEvidence(response), 'utf8');
      return outputPath;
    }),
  );

  return outputPaths;
}

async function main() {
  const inputDirectory = process.argv[2];
  const outputDirectory = process.argv[3] ? resolve(process.argv[3]) : defaultOutputDirectory;

  if (!inputDirectory) {
    throw new Error(
      'Supply the local, OneDrive-synchronised response directory as the first argument; no OneDrive credentials are read.',
