  }

  if (!document || typeof document !== 'object' || Array.isArray(document)) {
    throw new Error(`${sourcePath}: must contain a response object or a response-store object`);
  }

  return {
    schemaVersion: '1.0',
    responses: [document],
  };
}

function validationError(sourcePath, errors) {
  return new Error(`${sourcePath}: ${errors.join('; ')}`);
}

export async function ingestFeedbackFile(sourcePath, { schemaPath = defaultSchemaPath } = {}) {
  const [document, schema] = await Promise.all([readJson(sourcePath), readJson(schemaPath)]);
  const store = responseStoreFor(document, sourcePath);
  const validation = validateUserFeedbackStore(store, schema);

  if (!validation.valid) throw validationError(sourcePath, validation.errors);

  return store.responses.map(sanitiseResponse);
}

export async function ingestFeedbackDirectory(sourceDirectory, options = {}) {
  const entries = await readdir(sourceDirectory, { withFileTypes: true });
  const jsonFiles = entries
    .filter((entry) => entry.isFile() && extname(entry.name).toLowerCase() === '.json')
    .map((entry) => resolve(sourceDirectory, entry.name))
    .sort();
  const responses = [];

  for (const sourcePath of jsonFiles) {
    const fileResponses = await ingestFeedbackFile(sourcePath, options);
    responses.push(...fileResponses.map((response) => ({ ...response, sourceFile: basename(sourcePath) })));
  }

  return responses;
}

export async function readRawFeedbackFile(sourcePath) {
  return JSON.parse(await readFile(sourcePath, 'utf8'));
}

