import { mkdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { ingestFeedbackDirectory } from './user-feedback-ingestion.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const defaultOutputDirectory = resolve(repositoryRoot, 'docs/user-testing/evidence/generated');

const postTestLabels = {
  mostConfusing: 'Most confusing part',
  couldNotFind: 'Expected feature not found',
  unclearTerminology: 'Unclear terminology',
  mostIntuitive: 'Most intuitive part',
  oneChange: 'Suggested change',
  comfortableRepeatingTasks: 'Comfortable repeating tasks',
};

function markdownText(value) {
  return String(value).replaceAll('\r\n', '\n').replaceAll('\n', '<br>');
}

function markdownList(values, emptyMessage) {
  if (values.length === 0) return `- ${emptyMessage}`;
  return values.map((value) => `- ${markdownText(value)}`).join('\n');
}

function traceabilityValue(value) {
  return value ? `\`${value}\`` : 'Not recorded';
}

function findingsFor(response) {
  return response.tasks.flatMap((task) =>
    task.findings.map((finding) => ({
      ...finding,
      taskId: task.taskId,
    })),
  );
}

function severityRows(findings) {
  return ['S1', 'S2', 'S3', 'S4']
    .map(
      (severity) =>
        `| ${severity} | ${findings.filter((finding) => finding.severity === severity).length} |`,
    )
    .join('\n');
}

function completionStatus(response) {
  const total = response.tasks.length;
  const count = (outcome) => response.tasks.filter((task) => task.outcome === outcome).length;

  return [
    `- Success: ${count('success')} of ${total}`,
    `- Partial: ${count('partial')} of ${total}`,
    `- Failure: ${count('failure')} of ${total}`,
  ].join('\n');
}

function participantComments(response) {
  const entries = Object.entries(response.postTestResponses);
  if (entries.length === 0) return '- No participant comments recorded.';

  return entries
    .map(([key, value]) => {
      const label = postTestLabels[key] ?? key;
      const content = typeof value === 'boolean' ? (value ? 'Yes' : 'No') : markdownText(value);
      return `- **${label}:** ${content}`;
    })
    .join('\n');
}

export function renderUserTestingEvidence(response) {
  const findings = findingsFor(response);
  const observations = response.tasks.flatMap((task) =>
    task.observations.map((observation) => `${task.taskId}: ${observation}`),
  );
  const problems = findings.map(
    (finding) =>
      `${finding.findingId} (${finding.taskId}, ${finding.severity}): ${finding.summary} ` +
      `Decision: ${finding.decision}.`,
  );

  return `# User Testing Evidence

## Workflow Tested

- **Participant ID:** ${response.participantId}
- **Role:** ${response.role}
- **Session date:** ${response.sessionDate}
- **Workflow:** ${markdownText(response.workflowTested)}

## Tasks Attempted

| Task | Outcome |
| --- | --- |
${response.tasks.map((task) => `| ${task.taskId} | ${task.outcome} |`).join('\n')}

## Completion Status

${completionStatus(response)}

## Observations

${markdownList(observations, 'No observations recorded.')}

## Participant Comments

${participantComments(response)}

## Positive Findings

${markdownList(response.positiveFindings, 'No positive findings recorded.')}

## Usability Problems

${markdownList(problems, 'No usability problems recorded.')}

## Severity Classification

| Severity | Findings |
| --- | ---: |
${severityRows(findings)}

## Suggested Improvements

${markdownList(response.suggestedImprovements, 'No suggested improvements recorded.')}

## Traceability

- **Related Gitea issue:** ${traceabilityValue(response.traceability.relatedGiteaIssue)}
- **Implementation commit:** ${traceabilityValue(response.traceability.implementationCommit)}
- **Retest evidence:** ${traceabilityValue(response.traceability.retestEvidence)}
`;
}

function outputFilename(response) {
  return `${response.sessionDate}-${response.participantId}-${response.role}.md`;
}

export async function generateUserTestingEvidence(
  inputDirectory,
  outputDirectory = defaultOutputDirectory,
) {
  const responses = await ingestFeedbackDirectory(inputDirectory);
  const filenames = new Set();

  for (const response of responses) {
    const filename = outputFilename(response);
    if (filenames.has(filename)) {
      throw new Error(
        `Multiple responses would overwrite ${filename}; retain one session per participant/date/role.`,
      );
    }
    filenames.add(filename);
  }

  await mkdir(outputDirectory, { recursive: true });
  const outputPaths = await Promise.all(
    responses.map(async (response) => {
      const outputPath = resolve(outputDirectory, outputFilename(response));
      await writeFile(outputPath, renderUserTestingEvidence(response), 'utf8');
      return outputPath;
    }),
  );

  return outputPaths;
}

async function main() {
  const inputDirectory = process.argv[2];
  const outputDirectory = process.argv[3] ? resolve(process.argv[3]) : defaultOutputDirectory;

  if (!inputDirectory) {
    throw new Error(
      'Supply the local, OneDrive-synchronised response directory as the first argument; no OneDrive credentials are read.',
    );
  }

  const outputPaths = await generateUserTestingEvidence(resolve(inputDirectory), outputDirectory);
  console.log(
    `Generated ${outputPaths.length} user-testing evidence file(s) in ${outputDirectory}.`,
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`User-testing evidence generation failed: ${error.message}`);
    process.exitCode = 1;
  });
}

import { readdir } from 'node:fs/promises';
import { basename, extname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { readJson, validateUserFeedbackStore } from './validate-user-feedback.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const defaultSchemaPath = resolve(repositoryRoot, 'testing/user-feedback/schema.json');

function redactFreeText(value) {
  return value
    .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, '[redacted email]')
    .replace(/\b(?:\+?\d[\d .()-]{6,}\d)\b/g, '[redacted phone]')
    .replace(/\b(?:password|token|secret|api[ _-]?key)\s*[:=]\s*[^\s]+/gi, '[redacted credential]');
}

function sanitiseTextArray(values) {
  return values?.map(redactFreeText) ?? [];
}

function sanitiseResponse(response) {
  return {
    participantId: response.participantId,
    role: response.role,
    sessionDate: response.sessionDate,
    workflowTested: redactFreeText(response.workflowTested),
    tasks: response.tasks.map((task) => ({
      taskId: task.taskId,
      outcome: task.outcome,
      observations: sanitiseTextArray(task.observations),
      findings: task.findings.map((finding) => ({
        findingId: finding.findingId,
        summary: redactFreeText(finding.summary),
        severity: finding.severity,
        decision: finding.decision,
        relatedIssue: finding.relatedIssue,
        decisionReason: finding.decisionReason && redactFreeText(finding.decisionReason),
        retestRequired: finding.retestRequired,
      })),
    })),
    postTestResponses: Object.fromEntries(
      Object.entries(response.postTestResponses ?? {}).map(([key, value]) => [
        key,
        typeof value === 'string' ? redactFreeText(value) : value,
      ]),
    ),
    positiveFindings: sanitiseTextArray(response.positiveFindings),
    suggestedImprovements: sanitiseTextArray(response.suggestedImprovements),
    traceability: response.traceability ?? {},
  };
}

function responseStoreFor(document, sourcePath) {
  if (
    document &&
    typeof document === 'object' &&
    !Array.isArray(document) &&
    'responses' in document
  ) {
    return document;
  }

  if (!document || typeof document !== 'object' || Array.isArray(document)) {
    throw new Error(`${sourcePath}: must contain a response object or a response-store object`);
  }

  return {
    schemaVersion: '1.0',
    responses: [document],
  };
}

function validationError(sourcePath, errors) {
  return new Error(`${sourcePath}: ${errors.join('; ')}`);
}

async function ingestFeedbackFile(sourcePath, { schemaPath = defaultSchemaPath } = {}) {
  const [document, schema] = await Promise.all([readJson(sourcePath), readJson(schemaPath)]);
  const store = responseStoreFor(document, sourcePath);
  const validation = validateUserFeedbackStore(store, schema);

  if (!validation.valid) throw validationError(sourcePath, validation.errors);

  return store.responses.map(sanitiseResponse);
}

export async function ingestFeedbackDirectory(sourceDirectory, options = {}) {
  const entries = await readdir(sourceDirectory, { withFileTypes: true });
  const jsonFiles = entries
    .filter((entry) => entry.isFile() && extname(entry.name).toLowerCase() === '.json')
    .map((entry) => resolve(sourceDirectory, entry.name))
    .sort();
  const responses = [];

  for (const sourcePath of jsonFiles) {
    const fileResponses = await ingestFeedbackFile(sourcePath, options);
    responses.push(
      ...fileResponses.map((response) => ({ ...response, sourceFile: basename(sourcePath) })),
    );
  }

  return responses;
}

