import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import test from 'node:test';
import { tmpdir } from 'node:os';

import { generateUserTestingEvidence } from '../../scripts/generate-user-testing-evidence.mjs';
import { ingestFeedbackDirectory } from '../../scripts/user-feedback-ingestion.mjs';

function responseFixture(overrides = {}) {
  return {
    participantId: 'P01',
    role: 'public',
    sessionDate: '2026-09-08',
    workflowTested: 'Fixture-only public data discovery.',
    importSource: 'microsoft_forms_csv',
    tasks: [
      {
        taskId: 'PUB-01',
        outcome: 'partial',
        observations: [
          'Fixture comment: contact fixture@example.test or +27 82 555 0101.',
          'Fixture credential: token=fixture-secret.',
        ],
        findings: [
          {
            findingId: 'F01',
            summary: 'Fixture-only navigation problem.',
            severity: 'S2',
            decision: 'ux_improvement_issue_created',
            relatedIssue: '#428',
            decisionReason: 'Fixture-only improvement decision.',
            retestRequired: true,
          },
        ],
      },
    ],
    postTestResponses: {
      mostConfusing: 'Fixture-only comment.',
      comfortableRepeatingTasks: false,
    },
    positiveFindings: ['Fixture-only positive finding.'],
    suggestedImprovements: ['Fixture-only suggested improvement.'],
    traceability: {
      relatedGiteaIssue: '#428',
      implementationCommit: 'c5a4346c',
      retestEvidence: 'evidence/user-testing/sprint-2/retest.md',
    },
    ...overrides,
  };
}

async function withTemporaryDirectories(callback) {
  const root = await mkdtemp(join(tmpdir(), 'sport-analytics-user-feedback-'));
  const inputDirectory = join(root, 'input');
  const outputDirectory = join(root, 'output');

  await import('node:fs/promises').then(({ mkdir }) => mkdir(inputDirectory));
  try {
    await callback({ inputDirectory, outputDirectory });
  } finally {
    await rm(root, { recursive: true, force: true });
  }
}

test('ingests a single Power Automate response object and redacts supported PII patterns', async () => {
  await withTemporaryDirectories(async ({ inputDirectory }) => {
    await writeFile(
      join(inputDirectory, 'response.json'),
      `${JSON.stringify(responseFixture(), null, 2)}\n`,
      'utf8',
    );

    const responses = await ingestFeedbackDirectory(inputDirectory);

    assert.equal(responses.length, 1);
    assert.equal(responses[0].participantId, 'P01');
    assert.match(responses[0].tasks[0].observations[0], /\[redacted email\]/);
    assert.match(responses[0].tasks[0].observations[0], /\[redacted phone\]/);
    assert.match(responses[0].tasks[0].observations[1], /\[redacted credential\]/);
    assert.doesNotMatch(responses[0].tasks[0].observations.join('\n'), /fixture@example\.test/);
  });
});

test('generates MkDocs evidence with all required sections and traceability', async () => {
  await withTemporaryDirectories(async ({ inputDirectory, outputDirectory }) => {
    await writeFile(
      join(inputDirectory, 'response-store.json'),
      `${JSON.stringify({ schemaVersion: '1.0', responses: [responseFixture()] }, null, 2)}\n`,
      'utf8',
    );

    const generated = await generateUserTestingEvidence(inputDirectory, outputDirectory);
    const markdown = await readFile(generated[0], 'utf8');

    for (const heading of [
      '# User Testing Evidence',
      '## Workflow Tested',
      '## Tasks Attempted',
      '## Completion Status',
      '## Observations',
      '## Participant Comments',
      '## Positive Findings',
      '## Usability Problems',
      '## Severity Classification',
      '## Suggested Improvements',
      '## Traceability',
    ]) {
      assert.match(markdown, new RegExp(heading));
    }

    assert.match(markdown, /Related Gitea issue:\*\* `#428`/);
    assert.match(markdown, /Implementation commit:\*\* `c5a4346c`/);
    assert.match(markdown, /Retest evidence:\*\* `evidence\/user-testing\/sprint-2\/retest\.md`/);
    assert.doesNotMatch(markdown, /fixture@example\.test/);
    assert.doesNotMatch(markdown, /fixture-secret/);
  });
});

test('rejects a Power Automate response that includes a PII field', async () => {
  await withTemporaryDirectories(async ({ inputDirectory }) => {
    await writeFile(
      join(inputDirectory, 'invalid-response.json'),
      `${JSON.stringify(responseFixture({ email: 'fixture@example.test' }), null, 2)}\n`,
      'utf8',
    );

    await assert.rejects(ingestFeedbackDirectory(inputDirectory), /email: is not permitted/);
  });
});

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import { validateUserFeedbackStore } from '../../scripts/validate-user-feedback.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('../..', import.meta.url)));
const schema = JSON.parse(
  readFileSync(resolve(repositoryRoot, 'testing/user-feedback/schema.json'), 'utf8'),
);
const emptyStore = JSON.parse(
  readFileSync(resolve(repositoryRoot, 'testing/user-feedback/responses.json'), 'utf8'),
);

function responseFixture(overrides = {}) {
  return {
    participantId: 'P01',
    role: 'public',
    sessionDate: '2026-09-08',
    workflowTested: 'Fixture-only public discovery journey.',
    importSource: 'microsoft_forms_csv',
    tasks: [
      {
        taskId: 'PUB-01',
        outcome: 'success',
        observations: ['Fixture-only sanitised observation.'],
        findings: [],
      },
    ],
    ...overrides,
  };
}

function storeFixture(responseOverrides = {}) {
  return {
    schemaVersion: '1.0',
    responses: [responseFixture(responseOverrides)],
  };
}

test('the committed response store is valid and contains no fabricated responses', () => {
  const result = validateUserFeedbackStore(emptyStore, schema);

  assert.deepEqual(result, { valid: true, errors: [] });
  assert.deepEqual(emptyStore.responses, []);
});

test('accepts a sanitised Microsoft Forms response fixture', () => {
  const result = validateUserFeedbackStore(storeFixture(), schema);

  assert.deepEqual(result, { valid: true, errors: [] });
});

test('rejects unapproved PII-shaped fields', () => {
  const result = validateUserFeedbackStore(
    storeFixture({
      email: 'participant@example.test',
    }),
    schema,
  );

  assert.equal(result.valid, false);
  assert.match(result.errors.join('\n'), /email: is not permitted/);
});

test('rejects non-anonymous participant identifiers and malformed dates', () => {
  const result = validateUserFeedbackStore(
    storeFixture({
      participantId: 'Taylor Example',
      sessionDate: '2026-02-30',
    }),
    schema,
  );

  assert.equal(result.valid, false);
  assert.match(result.errors.join('\n'), /participantId: has an invalid format/);
  assert.match(result.errors.join('\n'), /sessionDate: must be a real ISO-8601 calendar date/);
});

test('rejects findings that omit their formal protocol decision data', () => {
  const result = validateUserFeedbackStore(
    storeFixture({
      tasks: [
        {
          taskId: 'PUB-01',
          outcome: 'partial',
          observations: ['Fixture-only observation.'],
          findings: [
            {
              findingId: 'F01',
              summary: 'Fixture-only finding.',
              severity: 'S2',
            },
          ],
        },
      ],
    }),
    schema,
  );

  assert.equal(result.valid, false);
  assert.match(result.errors.join('\n'), /decision: is required/);
  assert.match(result.errors.join('\n'), /retestRequired: is required/);
});

