import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

const ciWorkflow = readFileSync('.gitea/workflows/ci.yml', 'utf8');
const manualDocsWorkflow = readFileSync('.gitea/workflows/deploy-docs.yml', 'utf8');

function automaticDocsJob() {
  const marker = '\n  deploy_docs:';
  const start = ciWorkflow.indexOf(marker);
  assert.notEqual(start, -1, 'automatic docs deployment job must exist in CI');
  return ciWorkflow.slice(start);
}

test('automatic documentation deployment waits for validated main quality and published-doc routing', () => {
  const job = automaticDocsJob();

  assert.match(job, /needs:\s*\n\s*- plan\s*\n\s*- quality/);
  assert.match(job, /github\.event_name == 'push'/);
  assert.match(job, /github\.ref == 'refs\/heads\/main'/);
  assert.match(job, /needs\.plan\.outputs\.deployDocs == 'true'/);
});

test('automatic documentation deployment rebuilds the deployable site strictly and smoke checks Cloudflare', () => {
  const job = automaticDocsJob();

  assert.match(job, /python -m mkdocs build --strict/);
  assert.match(job, /wrangler pages deploy site --project-name=\$CLOUDFLARE_PROJECT_NAME/);
  assert.match(job, /smoke-check-deployment\.mjs/);
  assert.doesNotMatch(job, /npm run test:frontend/);
  assert.doesNotMatch(job, /npm run test:unit/);
  assert.doesNotMatch(job, /npm run test:e2e/);
});

test('standalone documentation deployment workflow is manual recovery only', () => {
  assert.match(manualDocsWorkflow, /workflow_dispatch:/);
  assert.doesNotMatch(manualDocsWorkflow, /\n\s*push:/);
  assert.match(manualDocsWorkflow, /python -m mkdocs build --strict/);
  assert.match(manualDocsWorkflow, /wrangler pages deploy site/);
});
import { mkdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { ingestFeedbackDirectory } from './user-feedback-ingestion.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const defaultOutputDirectory = resolve(repositoryRoot, 'docs/user-testing/evidence/generated');

function markdownText(value) {
  return String(value).replaceAll('\r\n', '\n').replaceAll('\n', '<br>');
}

function traceabilityValue(value) {
  return value ? `\`${value}\`` : 'Not recorded';
}

export function renderUserTestingEvidence(response) {
  return `# Sprint 2 User Testing Evidence

## Tested Workflow

- **Participant ID:** ${response.participant}
- **Workflow:** ${markdownText(response.workflow)}

## Tasks Attempted

${markdownText(response.tasksAttempted)}

## Completion Status

${markdownText(response.completionStatus)}

## Observations

${markdownText(response.observations)}

## Participant Comments

No separately captured participant comments were included in the anonymised Power Automate response.

## Positive Findings

${markdownText(response.positiveFindings)}

## Usability Problems

${markdownText(response.problems)}

## Severity Classification

${response.severity}

## Suggested Improvements

${markdownText(response.suggestions)}

## Traceability

- **Gitea issue:** ${traceabilityValue(response.traceability.giteaIssue)}
- **Implementation commit:** ${traceabilityValue(response.traceability.implementationCommit)}
- **Retesting evidence:** ${traceabilityValue(response.traceability.retestingEvidence)}
`;
}

function outputFilename(response, index) {
  return `${response.participant}-${String(index + 1).padStart(3, '0')}.md`;
}

export async function generateUserTestingEvidence(
  inputDirectory,
  outputDirectory = defaultOutputDirectory,
) {
  const responses = await ingestFeedbackDirectory(inputDirectory);
  await mkdir(outputDirectory, { recursive: true });

  return Promise.all(
    responses.map(async (response, index) => {
      const outputPath = resolve(outputDirectory, outputFilename(response, index));
      await writeFile(outputPath, renderUserTestingEvidence(response), 'utf8');
      return outputPath;
    }),
  );
}

async function main() {
  const inputDirectory = process.argv[2];
  const outputDirectory = process.argv[3] ? resolve(process.argv[3]) : defaultOutputDirectory;

  if (!inputDirectory) {
    throw new Error(
      'Supply the local OneDrive-synchronised response directory; no OneDrive credentials are read.',
    );
  }

  const outputPaths = await generateUserTestingEvidence(resolve(inputDirectory), outputDirectory);
  console.log(
    `Generated ${outputPaths.length} user-testing evidence file(s) in ${outputDirectory}.`,
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`User-testing evidence generation failed: ${error.message}`);
    process.exitCode = 1;
  });
}
import { readdir } from 'node:fs/promises';
import { basename, extname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { readJson, validateUserFeedbackStore } from './validate-user-feedback.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const defaultSchemaPath = resolve(repositoryRoot, 'testing/user-feedback/schema.json');

function redactFreeText(value) {
  return value
    .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, '[redacted email]')
    .replace(/\b(?:\+?\d[\d .()-]{6,}\d)\b/g, '[redacted phone]')
    .replace(/\b(?:password|token|secret|api[ _-]?key)\s*[:=]\s*[^\s]+/gi, '[redacted credential]');
}

function normaliseStore(document, sourcePath) {
  if (
    document &&
    typeof document === 'object' &&
    !Array.isArray(document) &&
    'responses' in document
  ) {
    return document;
  }
  if (!document || typeof document !== 'object' || Array.isArray(document)) {
    throw new Error(`${sourcePath}: must contain a feedback object or response-store object`);
  }

  return { schemaVersion: '1.0', responses: [document] };
}

function sanitiseResponse(response) {
  return {
    participant: response.participant,
    workflow: redactFreeText(response.workflow),
    tasksAttempted: redactFreeText(response.tasksAttempted),
    completionStatus: redactFreeText(response.completionStatus),
    observations: redactFreeText(response.observations),
    positiveFindings: redactFreeText(response.positiveFindings),
    problems: redactFreeText(response.problems),
    severity: response.severity,
    suggestions: redactFreeText(response.suggestions),
    traceability: response.traceability ?? {},
  };
}

async function ingestFeedbackFile(sourcePath, { schemaPath = defaultSchemaPath } = {}) {
  const [document, schema] = await Promise.all([readJson(sourcePath), readJson(schemaPath)]);
  const store = normaliseStore(document, sourcePath);
  const validation = validateUserFeedbackStore(store, schema);

  if (!validation.valid) throw new Error(`${sourcePath}: ${validation.errors.join('; ')}`);

  return store.responses.map(sanitiseResponse);
}

export async function ingestFeedbackDirectory(sourceDirectory, options = {}) {
  const entries = await readdir(sourceDirectory, { withFileTypes: true });
  const jsonFiles = entries
    .filter((entry) => entry.isFile() && extname(entry.name).toLowerCase() === '.json')
    .map((entry) => resolve(sourceDirectory, entry.name))
    .sort();
  const responses = [];

  for (const sourcePath of jsonFiles) {
    const fileResponses = await ingestFeedbackFile(sourcePath, options);
    responses.push(
      ...fileResponses.map((response) => ({ ...response, sourceFile: basename(sourcePath) })),
    );
  }

  return responses;
}
# Sprint 2 user-testing feedback store

This directory is the canonical, sanitised storage layer for formal Sprint 2 user-testing Power
Automate responses. It supports the protocol in
[`docs/testing/user-testing-protocol.md`](../../docs/testing/user-testing-protocol.md); it does not
replace the human facilitator's observations, consent checks, finding decisions, or retesting record.

## Files

- `responses.json` is the committed response store. It intentionally begins empty: no participant
  data is invented for this repository.
- `schema.json` is the versioned JSON Schema for normalised Power Automate responses.
- `../../scripts/validate-user-feedback.mjs` validates a response store against the schema without
  adding a runtime dependency.
- `../../scripts/generate-user-testing-evidence.mjs` ingests validated response files and writes
  sanitised MkDocs evidence pages under `docs/user-testing/evidence/generated/`.
- `tsconfig.json` applies the repository TypeScript checker to the executable ESM scripts without
  adding a separate transpilation runtime.

Validate the committed store from the repository root with:

```bash
node scripts/validate-user-feedback.mjs
```

Pass a normalised candidate file explicitly before replacing the committed store:

```bash
node scripts/validate-user-feedback.mjs path/to/sanitised-responses.json
```

Generate MkDocs evidence from a local OneDrive-synchronised directory of JSON response files:

```bash
node scripts/generate-user-testing-evidence.mjs "path/to/Sport Analytics/User Testing/responses"
```

## Privacy boundary

Only anonymous participant identifiers such as `P01` are accepted. The schema rejects unrecognised
fields, so `name`, `email`, phone-number, credential, and Microsoft Forms metadata fields cannot be
stored accidentally. Free-text observations still require a facilitator privacy review: do not enter
names, email addresses, passwords, tokens, API keys, or other identifying information.

Never commit a raw OneDrive export that includes respondent identity or timestamps. Keep the original
export in the team's approved restricted location and commit only reviewed, normalised JSON response
data.

## Power Automate JSON input

The generator reads local files synchronised by Power Automate from:

```text
OneDrive/Sport Analytics/User Testing/responses/*.json
```

Each JSON file must be either one response object or the response-store envelope. Every response
requires these fields:

| Input field        | Requirement                                           |
| ------------------ | ----------------------------------------------------- |
| `participant`      | Anonymous identifier matching `P01`, `P02`, and so on |
| `workflow`         | Tested workflow                                       |
| `tasksAttempted`   | Tasks attempted by the participant                    |
| `completionStatus` | Recorded completion status                            |
| `observations`     | Sanitised observation text                            |
| `positiveFindings` | Positive findings                                     |
| `problems`         | Usability problems                                    |
| `severity`         | Protocol severity `S1` to `S4`                        |
| `suggestions`      | Suggested improvements                                |

`traceability` is optional. When included, it may contain only `giteaIssue`,
`implementationCommit`, and a repository-relative `retestingEvidence` path. Name, email, phone,
credential, and Microsoft Forms metadata fields are rejected.

## Generated evidence

The generator redacts supported email-address, phone-number, and credential patterns in free-text
fields before writing Markdown. It emits one page per imported response with the workflow, tasks,
completion status, observations, comments, positive findings, usability problems, severity
classification, suggested improvements, and traceability.

## Response shape

```json
{
  "schemaVersion": "1.0",
  "responses": []
}
```

Populate the array only with real, reviewed, anonymised sessions that satisfy `schema.json`.
# Deploying the Documentation

## Prerequisites

- Python
- Node.js and npm
- A Cloudflare account
- Wrangler (run using `npx`)

## Install Documentation Dependencies

```bash
python -m pip install -r requirements-docs.txt
```

## Build the Documentation

Build the MkDocs site in strict mode to ensure there are no broken links or configuration errors.

```bash
python -m mkdocs build --strict
```

## Preview Locally

To preview the documentation before deployment:

```bash
python -m mkdocs serve
```

Open your browser at:

```
http://127.0.0.1:8000
```

## Deploy

Wrangler can authenticate either by logging in interactively or by using a Cloudflare API token.

Deploy the generated `site/` directory:

```bash
npx wrangler pages deploy site --project-name=sports-analytics-tool
```

For automated deployments, authentication should be provided using the following environment variables or repository secrets:

- `CLOUDFLARE_API_TOKEN`
- `CLOUDFLARE_ACCOUNT_ID`

## Public Documentation

Cloudflare Pages Project:

```
sports-analytics-tool
```

Public documentation URL:

https://sports-analytics-tool.pages.dev

## Automated Deployment

Automatic documentation deployment is part of `Sport Analytics CI`. Published documentation changes
are first validated by the change-aware CI flow; after merge, the `main` commit must pass the required
`quality` job before `deploy_docs` can publish to Cloudflare Pages.

The planner requests documentation deployment for production MkDocs inputs such as `docs/**`,
`mkdocs.yml` and `requirements-docs.txt`. Application-only, evidence-only and CI-only changes do not
redeploy the documentation site merely because a commit reached `main`.

On an automatic deployment, CI:

1. checks out the validated `main` commit;
2. validates `CLOUDFLARE_API_TOKEN` and `CLOUDFLARE_ACCOUNT_ID`;
3. installs the documentation dependencies;
4. builds the deployable site using:

   ```bash
   python -m mkdocs build --strict
   ```

5. installs the root workspace dependencies so the pinned Wrangler dependency is available;
6. deploys the generated `site/` directory using:

   ```bash
   npx wrangler pages deploy site --project-name=sports-analytics-tool
   ```

7. smoke checks the public documentation home page.

The strict MkDocs build is intentionally present both in validation and deployment: validation proves
the source before the quality decision, while deployment must create the generated `site/` artifact on
its own runner before Wrangler can publish it.

`.gitea/workflows/deploy-docs.yml` remains available as a manual `workflow_dispatch` recovery or
redeployment path. It no longer runs independently on every docs push to `main`, preventing a docs
publish from racing ahead of the shared post-merge quality and deployment decision.

The workflow authenticates using repository Actions secrets and never commits Cloudflare credentials:

- `CLOUDFLARE_API_TOKEN`
- `CLOUDFLARE_ACCOUNT_ID`

The Cloudflare API token should be limited to the permissions required to deploy the
`sports-analytics-tool` Pages project.

Manual Wrangler deployment using the commands above remains a local/fallback option when required.

## Failure interpretation

The job graph should be read as follows:

- `plan` failure: changed paths could not be safely planned, required structure/routing checks failed,
  committed patch whitespace failed, or the frozen npm lockfile check failed;
- `validation` skipped on a Pull Request: expected when npm-backed validation is not required;
- `validation` skipped on `main`: expected because the application quality suite already passed in the
  required up-to-date Pull Request;
- `validation` failure: one or more required formatting, hygiene, lint/typecheck, workspace
  tests/builds, PostgreSQL integration, documentation, deployment-helper, OpenAPI or manual coverage
  checks failed;
- `browser` skipped on a Pull Request: expected when browser validation is not required;
- `browser` skipped on `main`: expected on the deployment-only post-merge path;
- `browser` failure: the production browser build, Playwright journey or accessibility validation failed;
- `quality` failure: planning failed or a required Pull Request validation lane did not complete
  successfully;
- deployment failure after merge: source quality has already passed, but the target environment,
  deployment artifact or live smoke check needs investigation.

A failed required Pull Request check must be corrected in the branch. It must not be bypassed by
changing branch protection or weakening the planner merely to obtain a green Pull Request.

## Evidence and change control

For meaningful CI/CD changes, retain:

- the related issue and acceptance criteria;
- local command results;
- the Pull Request and peer approval;
- hosted Gitea Actions results/screenshots;
- before/after runner timing where optimisation is part of the issue;
- any discovered runner-specific defect and its resolution; and
- updated CI/testing/deployment documentation.

CI routing changes must add or update regression tests in `tests/ci/change-plan.test.mjs`. Changes
that alter what is required before merge must be reviewed against the Git methodology rather than
silently changing project process in YAML.

