import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import { basename, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const defaultInputDirectory = 'testing/user-feedback/input';
const safeJsonFilename = /^[A-Za-z0-9][A-Za-z0-9._-]*\.json$/i;

async function findJsonFiles(directory) {
  let entries;
  try {
    entries = await readdir(directory, { withFileTypes: true });
  } catch (error) {
    const code =
      error && typeof error === 'object' && 'code' in error && typeof error.code === 'string'
        ? error.code
        : undefined;
    if (code === 'ENOENT' || code === 'ENOTDIR') {
      throw new Error('User-testing feedback source directory does not exist.');
    }
    throw error;
  }

  const files = [];
  for (const entry of entries.sort((left, right) => left.name.localeCompare(right.name))) {
    const path = resolve(directory, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await findJsonFiles(path)));
    } else if (entry.isFile() && safeJsonFilename.test(entry.name)) {
      files.push(path);
    }
  }
  return files;
}

function normaliseJson(json) {
  try {
    return `${JSON.stringify(JSON.parse(json), null, 2)}\n`;
  } catch {
    throw new Error('A user-testing feedback file contains invalid JSON.');
  }
}

/**
 * Copies recursively discovered JSON files from a local OneDrive-synchronised directory into the
 * evidence pipeline input directory. Schema validation remains the ingestion module's responsibility.
 *
 * @param {string} sourceDirectory
 * @param {string} [destinationDirectory]
 */
export async function retrieveUserTestingFeedback(
  sourceDirectory,
  destinationDirectory = defaultInputDirectory,
) {
  const source = resolve(sourceDirectory);
  const destination = resolve(destinationDirectory);
  const sourceFiles = await findJsonFiles(source);

  await mkdir(destination, { recursive: true });
  const copiedNames = new Set();

  for (const sourceFile of sourceFiles) {
    const filename = basename(sourceFile);
    if (copiedNames.has(filename)) {
      throw new Error('User-testing feedback source contains duplicate JSON filenames.');
    }
    copiedNames.add(filename);
    await writeFile(
      resolve(destination, filename),
      normaliseJson(await readFile(sourceFile, 'utf8')),
      'utf8',
    );
  }

  return sourceFiles.length;
}

async function main() {
  const sourceDirectory = process.argv[2];
  if (!sourceDirectory) {
    throw new Error('Supply a local directory containing user-testing feedback JSON files.');
  }

  const count = await retrieveUserTestingFeedback(sourceDirectory);
  console.log(`Retrieved ${count} user-testing feedback JSON file(s).`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`User-testing feedback retrieval failed: ${error.message}`);
    process.exitCode = 1;
  });
}

import { mkdir, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { ingestFeedbackDirectory } from './user-feedback-ingestion.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const defaultOutputDirectory = resolve(repositoryRoot, 'docs/user-testing/evidence/generated');

function markdownText(value) {
  return String(value).replaceAll('\r\n', '\n').replaceAll('\n', '<br>');
}

function traceabilitySection(traceability) {
  const entries = [
    ['Gitea issue', traceability.giteaIssue],
    ['Implementation commit', traceability.implementationCommit],
    ['Retesting evidence', traceability.retestingEvidence],
  ].filter(([, value]) => value);

  if (entries.length === 0) return '';

  return `
## Traceability

${entries.map(([label, value]) => `- ${label}: ${value}`).join('\n')}
`;
}

export function renderUserTestingEvidence(response) {
  return `# Sprint 2 User Testing Evidence

## Tested Workflow

- **Participant ID:** ${response.participant}
- **Workflow:** ${markdownText(response.workflow)}

## Tasks Attempted

${markdownText(response.tasksAttempted)}

## Completion Status

${markdownText(response.completionStatus)}

## Observations

${markdownText(response.observations)}

## Participant Comments

No separately captured participant comments were included in the anonymised Power Automate response.

## Positive Findings

${markdownText(response.positiveFindings)}

## Usability Problems

${markdownText(response.problems)}

## Severity Classification

${response.severity}

## Suggested Improvements

${markdownText(response.suggestions)}${traceabilitySection(response.traceability)}
`;
}

function outputFilename(response, index) {
  return `${response.participant}-${String(index + 1).padStart(3, '0')}.md`;
}

export async function generateUserTestingEvidence(
  inputDirectory,
  outputDirectory = defaultOutputDirectory,
) {
  const responses = await ingestFeedbackDirectory(inputDirectory);
  await mkdir(outputDirectory, { recursive: true });

  return Promise.all(
    responses.map(async (response, index) => {
      const outputPath = resolve(outputDirectory, outputFilename(response, index));
      await writeFile(outputPath, renderUserTestingEvidence(response), 'utf8');
      return outputPath;
    }),
  );
}

async function main() {
  const inputDirectory = process.argv[2];
  const outputDirectory = process.argv[3] ? resolve(process.argv[3]) : defaultOutputDirectory;

  if (!inputDirectory) {
    throw new Error(
      'Supply the local OneDrive-synchronised response directory; no OneDrive credentials are read.',
    );
  }

  const outputPaths = await generateUserTestingEvidence(resolve(inputDirectory), outputDirectory);
  console.log(
    `Generated ${outputPaths.length} user-testing evidence file(s) in ${outputDirectory}.`,
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`User-testing evidence generation failed: ${error.message}`);
    process.exitCode = 1;
  });
}

import { readdir } from 'node:fs/promises';
import { extname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { readJson, validateUserFeedbackStore } from './validate-user-feedback.mjs';

const repositoryRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const defaultSchemaPath = resolve(repositoryRoot, 'testing/user-feedback/schema.json');

function redactFreeText(value) {
  return value
    .replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, '[redacted email]')
    .replace(/\b(?:\+?\d[\d .()-]{6,}\d)\b/g, '[redacted phone]')
    .replace(/\b(?:password|token|secret|api[ _-]?key)\s*[:=]\s*[^\s]+/gi, '[redacted credential]');
}

function normaliseStore(document) {
  if (
    document &&
    typeof document === 'object' &&
    !Array.isArray(document) &&
    'responses' in document
  ) {
    return document;
  }
  if (!document || typeof document !== 'object' || Array.isArray(document)) {
    throw new Error(
      'A user-testing feedback file must contain a feedback object or response-store object.',
    );
  }

  return { schemaVersion: '1.0', responses: [document] };
}

function sanitiseResponse(response) {
  return {
    participant: response.participant,
    workflow: redactFreeText(response.workflow),
    tasksAttempted: redactFreeText(response.tasksAttempted),
    completionStatus: redactFreeText(response.completionStatus),
    observations: redactFreeText(response.observations),
    positiveFindings: redactFreeText(response.positiveFindings),
    problems: redactFreeText(response.problems),
    severity: response.severity,
    suggestions: redactFreeText(response.suggestions),
    traceability: response.traceability ?? {},
  };
}

async function ingestFeedbackFile(sourcePath, { schemaPath = defaultSchemaPath } = {}) {
  const [document, schema] = await Promise.all([readJson(sourcePath), readJson(schemaPath)]);
  const store = normaliseStore(document);
  const validation = validateUserFeedbackStore(store, schema);

  if (!validation.valid)
    throw new Error(`User-testing feedback validation failed: ${validation.errors.join('; ')}`);

  return store.responses.map(sanitiseResponse);
}

export async function ingestFeedbackDirectory(sourceDirectory, options = {}) {
  const entries = await readdir(sourceDirectory, { withFileTypes: true });
  const jsonFiles = entries
    .filter((entry) => entry.isFile() && extname(entry.name).toLowerCase() === '.json')
    .map((entry) => resolve(sourceDirectory, entry.name))
    .sort();
  const responses = [];

  for (const sourcePath of jsonFiles) {
    const fileResponses = await ingestFeedbackFile(sourcePath, options);
    responses.push(...fileResponses);
  }

  return responses;
}

async function main() {
  const sourceDirectory = process.argv[2];
  if (!sourceDirectory)
    throw new Error('Supply a directory containing retrieved user-testing feedback JSON.');

  const responses = await ingestFeedbackDirectory(resolve(sourceDirectory));
  console.log(`Validated ${responses.length} user-testing feedback response(s).`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`User-testing feedback validation failed: ${error.message}`);
    process.exitCode = 1;
  });
}

